/**
 * MVP181 / PILOTO ONLY. Delayed supplier receipt thanks after classified
 * PDF/XLSX/image, with explicit FUTURE-ONLY DB activation and no backfill.
 * The sender comes ONLY from the signed Whapi trigger, never AI or a quote.
 * Reservation is a one-way idempotency barrier: timeout == terminal uncertain.
 */
const HEX=/^[a-f0-9]{64}$/u;
const CHAT=/^[1-9][0-9]{7,16}@s\.whatsapp\.net$/u;
export const DEFERRED_SUPPLIER_THANKS=
 '¡Gracias! Recibimos tu presupuesto. Lo estamos procesando en Cotironda.';
type Rpc=Readonly<{data:unknown;error:unknown}>;
type Sent=Readonly<{sent:boolean;id:string|null}>;
export type DeferredAckIO=Readonly<{
 rpc:(name:string,params:Record<string,unknown>)=>Promise<Rpc>;
 sendText:(recipient:string,text:string)=>Promise<Sent>;
}>;
export type AckOutcome='disabled'|'invalid'|'not_eligible'|
 'reserved_unavailable'|'api_accepted'|'uncertain'|'reconciliation_required';

/** No automatic retry of a reserved message — duplicate sends are worse
 * than a missing thank-you. All failed delivery states require audit.
 */
export async function sendDeferredSupplierAckMvp181(input:{
 enabled:boolean;messageHmac:string;triggerChatHmac:string;
 recipientChatId:string;io:DeferredAckIO
}):Promise<AckOutcome>{
 if(input.enabled!==true)return 'disabled';
 if(!HEX.test(input.messageHmac)||!HEX.test(input.triggerChatHmac)||
  !CHAT.test(input.recipientChatId))return 'invalid';
 let reservation:Rpc;
 try{
  reservation=await input.io.rpc(
   'cotironda_piloto_reserve_deferred_supplier_ack_mvp181',{
    p_message_hmac:input.messageHmac,
    p_trigger_chat_hmac:input.triggerChatHmac
   });
 }catch{return 'reserved_unavailable'}
 if(reservation.error)return 'reserved_unavailable';
 if(reservation.data!==true)return 'not_eligible';
 // The reservation was persisted before ANY network call. Never reserve
 // again on Whapi transport error, timeout, malformed response or crash.
 let state:'api_accepted'|'uncertain'='uncertain';
 let whapiMessageId:string|null=null;
 try{
  const sent=await input.io.sendText(
   input.recipientChatId,DEFERRED_SUPPLIER_THANKS);
  if(sent?.sent===true){
   state='api_accepted';
   if(typeof sent.id==='string'&&
    /^[A-Za-z0-9_-]{8,160}$/u.test(sent.id))whapiMessageId=sent.id;
  }
 }catch{/* Unknown delivery is terminal, not a reason to repeat. */}
 try{
  const finish=await input.io.rpc(
   'cotironda_piloto_finish_supplier_ack_mvp104',{
    p_message_hmac:input.messageHmac,p_state:state
   });
  if(finish.error||finish.data!==true)return 'reconciliation_required';
  if(state==='api_accepted'&&whapiMessageId){
   const id=await input.io.rpc(
    'cotironda_piloto_record_supplier_ack_id_mvp119',{
     p_message_hmac:input.messageHmac,p_whapi_message_id:whapiMessageId
    });
   if(id.error||id.data!==true)return 'reconciliation_required';
  }
 }catch{return 'reconciliation_required'}
 return state;
}

/**
 * MVP138: independently verify an archived supplier draft against actual bytes.
 * This proves textual fidelity, NOT economic comparability or buyer approval.
 */
import type {DownloadedMedia} from './whapi-media-archive.ts';
import type {DocumentDraft} from './document-ai-draft.ts';
import {readPdfPositioned} from './supplier-source-pdf-general.ts';
import {readOfficeVisibleRows} from './supplier-source-office.ts';

type Reason='covered'|'invalid_input'|'unreadable'|'missing_line'|
 'missing_amount'|'missing_total'|'uncovered_note'|'extra_charge'|'ambiguous';
export type Evidence={state:'verified'|'needs_source_review';reason:Reason;lines:number};
type Reader=(source:DownloadedMedia)=>Promise<readonly string[]>;
const n=(x:string)=>x.normalize('NFKC').toLocaleLowerCase('es-AR').replace(/\s+/gu,' ').trim();
const scalar=(x:string)=>n(x).replace(/^\$\s*/u,'').replace(/\s+/gu,'');
const num=(x:string)=>/^\d+(?:[.,]\d+)*$/u.test(scalar(x));
const escape=(x:string)=>[...x].map(c=>'\\.^$*+?()[]{}|'.includes(c)?'\\'+c:c).join('');
const has=(hay:string,x:string)=>num(x)&&
 new RegExp('(?<![\\p{L}\\p{N}.,])'+escape(scalar(x))+'(?![\\p{L}\\p{N}.,])','u')
 .test(n(hay).replace(/\$\s*/gu,''));
const cash=(x:string)=>Array.from(x.matchAll(/\$\s*\d[\d.,]*/gu),m=>scalar(m[0]));
const reject=(reason:Reason,lines:number):Evidence=>({state:'needs_source_review',reason,lines});
const nonmaterial=(x:string)=>/^(?:no se especifica el tratamiento del iva|no se indica disponibilidad|la moneda no est[aá] identificada expl[ií]citamente)/iu.test(n(x));
const minor=(x:string|null)=>x===null||x.trim()===''||
 /^unidad de cantidad no indicada\.?(?: descuento visible:\s*\d{1,2}[.,]\d{1,2}%\.?)?$/iu.test(n(x));
const discount=(x:string|null)=>x?.match(/descuento visible:\s*(\d{1,2}[.,]\d{1,2})\s*%/iu)?.[1]??null;
/** Some PDFs have a Dscto column: the model may append its value after
 * the product name even though the source prints it as a separate cell.
 * This removes the suffix ONLY for finding the product line. Its numeric
 * value still requires an independent source percentage and exact math. */
const discountFromDescription=(literal:string):{description:string;rate:string|null}=>{
 const m=literal.match(/;\s*dscto\.?\s*:?\s*(\d{1,2}[.,]\d{1,2})\s*%$/iu);
 return m&&m.index!==undefined
  ?{description:literal.slice(0,m.index).trim(),rate:m[1]}
  :{description:literal,rate:null};
};

/** Decimal percentages are compared in exact basis points: 22,4 = 22,40.
 * Some supplier PDFs place Dscto in a separate column/text object.
 * Only accept a global discount when amount math independently corroborates. */
const basis=(v:string):bigint|null=>{
 const m=v.trim().replace('.',',').match(/^(\d{1,2})(?:,(\d{1,2}))?$/u);
 if(!m)return null;
 const b=BigInt(m[1])*100n+BigInt((m[2]??'').padEnd(2,'0'));
 return b<10000n?b:null;
};
const cents=(v:string):bigint|null=>{
 let t=scalar(v);
 if(/^\d{1,3}(?:\.\d{3})+,\d{2}$/u.test(t))t=t.replace(/\./gu,'');
 else if(!/^\d+(?:,\d{2})?$/u.test(t))return null;
 const [integer,decimal='']=t.split(',');
 return BigInt(integer)*100n+BigInt(decimal.padEnd(2,'0'));
};
const hundredths=(v:string):bigint|null=>{
 let t=scalar(v).replace('.',',');
 if(!/^\d+(?:,\d{1,2})?$/u.test(t))return null;
 const [a,b='']=t.split(',');
 return BigInt(a)*100n+BigInt(b.padEnd(2,'0'));
};
const discountMath=(line:DocumentDraft['lines'][number],rate:bigint)=>{
 const qty=hundredths(line.quantity??'');
 const unit=cents(line.unit_price??'');
 const extended=cents(line.line_total??'');
 if(qty===null||unit===null||extended===null)return false;
 const numerator=unit*qty*(10000n-rate);
 const actual=extended*100n*10000n;
 const diff=numerator>actual?numerator-actual:actual-numerator;
 // Up to 10 cents difference in a quantity × rounded two-decimal list price,
 // preserving the supplier's DECLARED line total without recalculation.
 return diff<=10n*100n*10000n;
};
const percentSeen=(rows:readonly string[],discount:bigint)=>rows.some(row=>
 [...row.matchAll(/(\d{1,2}(?:[.,]\d{1,2})?)\s*%/gu)]
 .some(m=>basis(m[1])===discount) ||
 (/(?:descuento|dscto|bonificaci[oó]n)/iu.test(row) &&
 [...row.matchAll(/(?<!\d)(\d{1,2}[.,]\d{1,2})(?!\d)/gu)]
  .some(m=>basis(m[1])===discount))
);
const discountProof=(row:string,rows:readonly string[],
 line:DocumentDraft['lines'][number],value:string)=>{
 if(has(row,value))return true;
 const d=basis(value);
 if(d===null)return false;
 return percentSeen(rows,d)&&
  rows.some(x=>/\b(?:descuento|dscto|bonificaci[oó]n)\b/iu.test(x))&&
  discountMath(line,d);
};

const pii=/(?:https?:\/\/|wa\.me|www\.|whatsapp|cuit|cuil|tel[eé]fono|raz[oó]n social|[a-z0-9._%+-]+@[a-z0-9.-]+|[0-9]{8,})/iu;
const commercial=/(?:\biva\b|flete|pallet|bolson|devoluci[oó]n|lista|contado|efectivo|plazo|entrega|env[ií]o|transporte|cargo|pago|transferencia|descuento)/iu;
/**
 * PDF text objects may be emitted in a different order from the printed
 * commercial clauses. Prove EVERY significant word and number against
 * unconsumed original text; never discard negations or numeric conditions.
 * Order is deliberately not used as an authenticity signal.
 */
const clauseTokens=(value:string):readonly string[]=>{
 const stop=new Set(['a','al','de','del','el','en','la','las','los','y']);
 return (n(value).normalize('NFD').replace(/\p{M}/gu,'')
  .match(/[\p{L}]+|\d+(?:[.,]\d+)*%?/gu)??[])
  .map(word=>word==='precios'?'precio':word==='dias'?'dia':word)
  .filter(word=>!stop.has(word));
};
const coveredTokens=(evidence:string,claim:string):boolean=>{
 const found=new Set(clauseTokens(evidence));
 return clauseTokens(claim).every(word=>found.has(word));
};
/** Only financial conditions (not PDF table headers / labels) are material.
 * Numeric conditions are compared exactly, ignoring leading zeros only.
 * An unclaimed negation, payment term, shipping charge or nonzero number
 * still blocks publication. Monetary figures are rejected separately.
 */
const materialTokens=(value:string):readonly string[]=>{
 const protectedTerms=new Set([
  'no','sin','iva','flete','pallet','bolson','devolucion','lista',
  'contado','efectivo','plazo','entrega','envio','transporte','cargo',
  'pago','transferencia','descuento','bonificacion','incluido','excluido',
  'convenir','credito','impuesto','disponibilidad','anticipo','dia',
  'precio','condicion','garantia','vencimiento','retornable','financiacion'
 ]);
 return clauseTokens(value).filter(word=>protectedTerms.has(word)||/^\d+(?:[.,]\d+)*%?$/u.test(word))
  .map(word=>/^0+$/u.test(word)?'0':word.replace(/^0+(?=\d)/u,''));
};
const commercialNotesCovered=(note:string,row:string):boolean=>{
 const noteSet=new Set(materialTokens(note));
 return materialTokens(row).every(word=>noteSet.has(word));
};
const headerWithoutPrices=(row:string):boolean=>
 /\b(?:item|cant(?:idad)?)\b/iu.test(row)&&
 /\b(?:descripcion|descripci[oó]n|producto)\b/iu.test(row)&&
 /\b(?:subtotal|unit|precio|importe)\b/iu.test(row)&&
 !/\d+(?:[.,]\d+)?\s*%/u.test(row);
const discountOnly=(row:string,claimed:readonly bigint[]):boolean=>{
 const m=n(row).match(/^(?:descuento|dscto|bonificacion)\s*:?\s*(\d{1,2}(?:[.,]\d{1,2})?)\s*%?$/u);
 const rate=m?basis(m[1]):null;
 return rate!==null&&claimed.includes(rate);
};

const sourceReader:Reader=async f=>{
 if(f.mime==='application/pdf'){
  const pdf=await readPdfPositioned(f.bytes);
  return pdf.scanned?[]:pdf.rows.map(x=>x.text);
 }
 if(f.mime.includes('openxmlformats-officedocument'))return readOfficeVisibleRows(f);
 if(f.mime==='text/plain'||f.mime==='text/csv')
  return new TextDecoder('utf-8',{fatal:true}).decode(f.bytes).split(/\r?\n/gu).filter(Boolean);
 return [];
};
export async function verifySupplierEvidence(
 f:DownloadedMedia,p:DocumentDraft,read:Reader=sourceReader
):Promise<Evidence>{
 const c=p?.lines?.length??0;
 if(!f||!(f.bytes instanceof Uint8Array)||f.bytes.length<120||
  f.bytes.length>8388608||!/^[a-f0-9]{64}$/u.test(f.sha256)||
  !p||p.kind!=='supplier_quote'||c<1||c>25||!p.total_declared||
  !num(p.total_declared)||!Array.isArray(p.unanswered))
  return reject('invalid_input',c);
 if(p.unanswered.some(q=>!nonmaterial(q))||
  p.lines.some(l=>!l.original_description||!l.quantity||!l.unit_price||
   !l.line_total||!num(l.quantity)||!num(l.unit_price)||!num(l.line_total)||
   !minor(l.ambiguity)||pii.test(l.original_description))||
  pii.test(p.requested_delivery_note??''))
  return reject('ambiguous',c);
 let rows:readonly string[];
 try{rows=await read(f)}catch{return reject('unreadable',c)}
 if(rows.length<2||rows.length>300)return reject('unreadable',c);
 const source=rows.map(n),used=new Set<number>();
 for(const l of p.lines){
  const dsc=discountFromDescription(l.original_description);
  const i=source.findIndex((row,j)=>!used.has(j)&&row.includes(n(dsc.description))&&
   has(row,l.quantity!)&&has(row,l.unit_price!)&&has(row,l.line_total!));
  if(i<0)return reject('missing_line',c);
  if(dsc.rate!==null){
   const rate=basis(dsc.rate);
   // Neither the AI text nor a table header is proof of a discount.
   // Require an original visible percent, a source Dscto/discount label,
   // AND deterministic arithmetic using the supplier's literal numbers.
   if(rate===null||!discountMath(l,rate)||!percentSeen(source,rate)||
     !source.some(row=>/\b(?:dscto|descuento|bonificaci[oó]n)\b/iu.test(row)))
    return reject('missing_amount',c);
  }
  const d=discount(l.ambiguity);
  if(d&&!discountProof(source[i],source,l,d))return reject('missing_amount',c);
  const m=cash(source[i]);
  for(const v of [l.unit_price!,l.line_total!]){
   const pos=m.indexOf(scalar(v));if(pos>=0)m.splice(pos,1);
  }
  if(m.length)return reject('extra_charge',c);
  if(f.mime==='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'){
   // All bare numeric XLSX cells are source amounts, not just $-prefixed ones.
   const cells=source[i].split('·').map(v=>v.trim()).filter(v=>num(v));
   const expected=[l.quantity!,l.unit_price!,l.line_total!].map(scalar);
   for(const wanted of expected){
    const at=cells.findIndex(v=>scalar(v)===wanted);
    if(at<0)return reject('missing_amount',c);
    cells.splice(at,1);
   }
   if(cells.length)return reject('extra_charge',c);
  }
  used.add(i);
 }
 // Commercial PDFs often print TOTAL and its amount on adjacent text baselines.
 // Reconcile only an unambiguous, isolated amount right next to the label.
 // Every unconsumed monetary row still blocks publication.
 const label=/\b(?:total(?:\s+(?:general|final|a\s+pagar|presupuesto))?|importe\s+(?:total|a\s+pagar|final)|monto\s+a\s+pagar|neto\s+a\s+pagar|a\s+pagar)\b/iu;
 const inline=source.map((row,i)=>({row,i,consumed:[i]})).filter(({row,i})=>
  !used.has(i)&&label.test(row)&&has(row,p.total_declared!));
 const amountOnly=(row:string)=>/^\s*\$?\s*\d[\d.,]*\s*$/u.test(row)&&
  has(row,p.total_declared!);
 const split=source.flatMap((row,i)=>{
  if(used.has(i)||!label.test(row)||cash(row).length||
   /(?<![\p{L}\p{N}])\d[\d.,]*(?![\p{L}\p{N}])/u.test(row))
   return [] as {row:string;i:number;consumed:number[]}[];
  const neighbors=[i-1,i+1].filter(j=>j>=0&&j<source.length&&
   !used.has(j)&&amountOnly(source[j]));
  return neighbors.map(j=>({row:source[j],i,consumed:[i,j]}));
 });
 let totals=[...inline,...split];
 // The source PDF may have NO machine-readable TOTAL label; only source
 // amounts, an unambiguous money field and exact line-sum math are trusted.
 // Accept only one standalone, original-value money field, with the
 // deterministic sum of ALL quoted line totals equal to the claimed total.
 // All other unclaimed charges and conditions are still audited below.
 if(totals.length===0&&f.mime==='application/pdf'){
  const totalValue=cents(p.total_declared!);
  const values=p.lines.map(l=>cents(l.line_total??''));
  if(totalValue!==null&&values.every((v):v is bigint=>v!==null)&&
   values.reduce((a,v)=>a+(v??0n),0n)===totalValue){
   const noteEvidence=n(p.requested_delivery_note??'');
   const totalQualifiers=/\b(?:contado|efectivo|transferencia|iva|pago|plazo|lista|entrega)\b/giu;
   const otherCharge=/(?:pallet|bolson|flete|cargo|descuento|unitario|cemento|hidrofug|transporte|env[ií]o)/iu;
   const isolated=source.map((row,i)=>({row,i,consumed:[i]}))
    .filter(({row,i})=>!used.has(i)&&has(row,p.total_declared!)&&
      cash(row).length===1&&cash(row)[0]===scalar(p.total_declared!)&&
      !otherCharge.test(row)&&
      [...row.matchAll(totalQualifiers)].every(m=>noteEvidence.includes(m[0])));
   if(isolated.length===1)totals=isolated;
  }
 }
 if(totals.length!==1)return reject('missing_total',c);
 if(cash(totals[0].row).length>1)return reject('extra_charge',c);
 for(const i of totals[0].consumed)used.add(i);
 const note=n(p.requested_delivery_note??'');
 // Only unmatched source rows may prove commercial notes. A product
 // name or a price already consumed cannot masquerade as a payment term.
 // A verified TOTAL row can also say CONTADO; reuse only its text
 // qualifiers, never the monetary digits, as evidence for a payment note.
 const totalRowWords=clauseTokens(totals[0].row)
  .filter(word=>!/\d/u.test(word)).join(' ');
 const unclaimedSource=source.filter((_,i)=>!used.has(i)).join(' ')+
  ' '+totalRowWords;
 if(note&&!coveredTokens(unclaimedSource,note))
  return reject('uncovered_note',c);
 const claimedDiscounts=p.lines.flatMap(l=>[
   discount(l.ambiguity),discountFromDescription(l.original_description).rate])
  .filter((d):d is string=>d!==null).map(basis)
  .filter((d):d is bigint=>d!==null);
 for(const [i,row] of source.entries()){
  if(used.has(i))continue;
  // A supplier can submit prices without the $ sign. Unclaimed numeric
  // spreadsheet cells and bare PDF currency must never disappear.
  const bareCurrency=/(?<![\p{L}\p{N}])(?:\d{1,3}(?:\.\d{3})+(?:,\d{2})?|\d+,\d{2})(?![\d.,%])/u;
  const excelNumbers=f.mime==='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'?
   row.split('·').filter(v=>num(v.trim())).length:0;
  if(cash(row).length||bareCurrency.test(row)||
   excelNumbers>=2||excelNumbers>=1&&commercial.test(row))
   return reject('extra_charge',c);
  if(commercial.test(row)&&!commercialNotesCovered(note,row)&&
    !discountOnly(row,claimedDiscounts)&&!headerWithoutPrices(row)&&
    !/^\s*(?:descripci[oó]n|producto|cantidad|precio|importe)\b/iu.test(row))
   return reject('uncovered_note',c);
 }
 return {state:'verified',reason:'covered',lines:c};
}

/**
 * MVP252 — OCR independiente opcional de Google Cloud Vision, NUNCA IA Central.
 * No se invoca por defecto. No transforma este resultado en una publicación.
 * Supabase Edge no ejecuta Tesseract/Workers: delegar I/O a HTTPS fijo.
 *
 * Exige una cuenta de servicio configurada fuera de GitHub, consentimiento
 * para tratamiento externo, cuotas/costos autorizados y SHA del original.
 */
import type {DownloadedMedia} from './whapi-media-archive.ts';

export type VisualOCRMvp252=Readonly<{
 sourceSha256:string;mime:string;pages:number;
 text:string;provider:'google_cloud_vision';minConfidence:number;
}>;
type Config=Readonly<{
 enabled:boolean;serviceAccountJson:string;
 consented:boolean;pages?:number;
 fetchImpl?:typeof fetch;
}>;
const MIMES=new Set(['image/jpeg','image/png','image/webp','application/pdf']);
const HEX=/^[a-f0-9]{64}$/u;
const AUD='https://oauth2.googleapis.com/token';
const VISION='https://vision.googleapis.com/v1/';
const SCOPE='https://www.googleapis.com/auth/cloud-vision';
const MAX_SOURCE=3*1024*1024; // Base64 / JSON y memoria, no cuota sin límite
const MAX_RESULT=120000;
const MAX_OCR_TEXT=18000;
const safe=(v:unknown):v is Record<string,unknown>=>
 !!v&&typeof v==='object'&&!Array.isArray(v);
function err(code:string):never {throw Error('visual_ocr_'+code)}
function binaryBase64(bytes:Uint8Array):string{
 let s='';
 for(let i=0;i<bytes.length;i+=8192)
  s+=String.fromCharCode(...bytes.subarray(i,i+8192));
 return btoa(s);
}
function url64(bytes:Uint8Array):string{
 return binaryBase64(bytes).replace(/\+/gu,'-').replace(/\//gu,'_').replace(/=/gu,'');
}
function signature(bytes:Uint8Array,mime:string):boolean{
 const prefix=(...values:number[])=>values.every((v,i)=>bytes[i]===v);
 if(mime==='image/jpeg')return prefix(0xff,0xd8,0xff);
 if(mime==='image/png')return prefix(0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a);
 if(mime==='image/webp')return prefix(0x52,0x49,0x46,0x46)&&
   bytes[8]===0x57&&bytes[9]===0x45&&bytes[10]===0x42&&bytes[11]===0x50;
 return prefix(0x25,0x50,0x44,0x46,0x2d);
}
async function assertOriginal(file:DownloadedMedia):Promise<void>{
 if(!file||!MIMES.has(file.mime)||
   !(file.bytes instanceof Uint8Array)||
   file.bytes.length<12||file.bytes.length>MAX_SOURCE||
   !HEX.test(file.sha256)||!signature(file.bytes,file.mime))
   err('invalid_source');
 const h=await crypto.subtle.digest('SHA-256',Uint8Array.from(file.bytes));
 const actual=[...new Uint8Array(h)].map(v=>v.toString(16).padStart(2,'0')).join('');
 if(actual!==file.sha256)err('hash_mismatch');
}
function credentials(raw:string):{client_email:string;private_key:string}{
 if(typeof raw!=='string'||raw.length<150||raw.length>16000)err('no_credentials');
 let data:unknown;
 try{data=JSON.parse(raw)}catch{err('no_credentials')}
 if(!safe(data)||data.type!=='service_account'||
   typeof data.client_email!=='string'||
   !/^[a-z0-9_.-]{3,100}@[a-z0-9-]+\.iam\.gserviceaccount\.com$/u.test(data.client_email)||
   typeof data.private_key!=='string'||
   !data.private_key.startsWith('-----BEGIN PRIVATE KEY-----')||
   !data.private_key.trim().endsWith('-----END PRIVATE KEY-----'))
   err('no_credentials');
 return {client_email:data.client_email as string,private_key:data.private_key as string};
}
async function serviceAccountAssertion(c:{client_email:string;private_key:string}):Promise<string>{
 const clean=c.private_key.replace(/-----BEGIN PRIVATE KEY-----|-----END PRIVATE KEY-----|\s/gu,'');
 let der:Uint8Array;
 try{der=Uint8Array.from(atob(clean),s=>s.charCodeAt(0))}
 catch{err('invalid_private_key')}
 let key:CryptoKey;
 try{key=await crypto.subtle.importKey('pkcs8',Uint8Array.from(der),{
   name:'RSASSA-PKCS1-v1_5',hash:'SHA-256'
 },false,['sign'])}catch{err('invalid_private_key')}
 const now=Math.floor(Date.now()/1000);
 const encoded=(v:unknown)=>url64(new TextEncoder().encode(JSON.stringify(v)));
 const unsigned=encoded({alg:'RS256',typ:'JWT'})+'.'+encoded({
  iss:c.client_email,scope:SCOPE,aud:AUD,iat:now,exp:now+1800
 });
