 const incl=/\b(?:iva\s+incluido|con\s+iva)\b/u.test(all);
 const excl=/\b(?:sin\s+iva|iva\s+no\s+incluido|iva\s+aparte)\b/u.test(all);
 const rate=/\b(?:iva\s*(?:al\s*)?(?:21|10[,.]5|0)\s*%|(?:21|10[,.]5|0)\s*%\s*iva)\b/u.test(all);
