const SHA=/^[a-f0-9]{64}$/u;
const PII=/(?:\bcuit\b|\bcuil\b|whats?app|celular|tel[eé]fono|raz[oó]n social|direcci[oó]n|contacto|https?:\/\/|wa\.me|@[\w.-]+|[\w.%+-]+@[\w.-]+\.[a-z]{2,}|\+54[\s-]*\d)/iu;
