 if(a.source.mime==='application/pdf'){
  let inspection:PdfSourceEvidence;
  try{inspection=await (a.inspectPdf??readPdfPositioned)(a.source.bytes)}
  catch{return audit('needs_review','pdf_inspection_failed',a.source)}
